USE transport_db;
SET NAMES utf8mb4;
SET time_zone = '-06:00';











UPDATE pedidos SET codigo = CONCAT('PED-', YEAR(creado_en), '-', LPAD(id, 5, '0'));




UPDATE pedidos_internos SET codigo = CONCAT('PI-', YEAR(creado_en), '-', LPAD(id, 5, '0'));










UPDATE alquileres SET codigo = CONCAT('ALQ-', YEAR(creado_en), '-', LPAD(id, 5, '0'));



UPDATE viajes SET codigo = CONCAT('VIA-', YEAR(creado_en), '-', LPAD(id, 5, '0'));



UPDATE ordenes_produccion SET codigo = CONCAT('OP-', YEAR(creado_en), '-', LPAD(id, 5, '0'));



UPDATE proyectos SET codigo = CONCAT('PRY-', YEAR(creado_en), '-', LPAD(id, 5, '0'));





